import random

def generate_random_selection(variable_list):
    if not variable_list:
        return []

    selection = []
    queue = [None] * 2  # Create a queue to keep track of previously selected variables
    queue_index = 0

    while len(selection) < len(variable_list):
        # Generate a random index within the range of the remaining variables
        index = random.randint(0, len(variable_list) - len(selection) - 1)

        # Find the variable at the random index
        for i, variable in enumerate(variable_list):
            if index == 0:
                # If the variable is not the same as the one before it in the queue, add it to the selection
                if i != queue[queue_index-1]:
                    selection.append(variable)
                    # Update the queue and index to keep track of the last two selected variables
                    queue[queue_index] = i
                    queue_index = (queue_index + 1) % 2
                break
            if index > 0:
                index -= 1

    return selection

