    if patient.severity < 3:
        score += 1
    else:
        score += 2

    # Increase priority based on the number of comorbidities
    comorbidity_level = {0: 1, 1: 1, 2: 2, 3: 2, 4: 3}
    score += comorbidity_level.get(patient.comorbidities, 0)

