    duration_group = {4: 1, 8: 2, 16: 3, float('inf'): 4}
    for duration, group_score in duration_group.items():
        if patient.duration_of_condition < duration:
            score += group_score
            break

    # Increase priority based on the presence of symptoms
    if 'seeping fluid' in patient.symptoms or 'pain' in patient.symptoms:
